package com.yara.ai.games
class TicTacToeGame{var board=MutableList(9){0};var over=false;fun move(i:Int,p:Int):Boolean{if(i !in 0..8||board[i]!=0||over)return false;board[i]=p;over=winner()!=0||board.all{it!=0};return true};fun winner():Int{val l=listOf(0 to 1 to 2,3 to 4 to 5,6 to 7 to 8,0 to 3 to 6,1 to 4 to 7,2 to 5 to 8,0 to 4 to 8,2 to 4 to 6);return l.firstOrNull{board[it.first]==board[it.second]&&board[it.first]==board[it.third]&&board[it.first]!=0}?.let{board[it.first]}?:0};fun ai():Int{val free=board.indices.filter{board[it]==0};var best=-1;var score=-2;for(i in free){board[i]=2;val s=minimax(false);board[i]=0;if(s>score){score=s;best=i}};if(best>=0)move(best,2);return best};private fun minimax(max:Boolean):Int{val w=winner();if(w==2)return 1;if(w==1)return -1;if(board.all{it!=0})return 0;var v=if(max)-2 else 2;for(i in board.indices)if(board[i]==0){board[i]=if(max)2 else 1;v=if(max)kotlin.math.max(v,minimax(false))else kotlin.math.min(v,minimax(true));board[i]=0};return v}}
